  1: - name: Create directories
  2:   ansible.builtin.file:
  3:     path: "{{ target }}/{{ item.path }}"
  4:     state: directory
  5:     owner: "{{ settings.owner | default(omit) }}"
  6:     group: "{{ settings.group | default(omit) }}"
  7:     mode: "{{ settings.mode | default('755', true) }}"
  8:   vars:
  9:     settings: >-
 10:       {{
 11:         files[item.path] |
 12:         default(fnmatch_candidates | first) |
 13:         default(None)
 14:       }}
 15:     fnmatch_candidates_yaml: |
 16:       {% for entry in files | ansible.builtin.dict2items %}
 17:       {% if item.path is fnmatch(entry.key) %}
 18:       - # for debugging, the key of the follow object is: {{ entry.key }}
 19:         {{ entry.value }}
 20:       {% endif %}
 21:       {% endfor %}
 22:     fnmatch_candidates: >-
 23:       {{
 24:         fnmatch_candidates_yaml |
 25:         ansible.builtin.from_yaml |
 26:         default([], true) |
 27:         list
 28:       }}
 29:     root_directory: >-
 30:       {{
 31:         {
 32:           'path': ''
 33:         }
 34:       }}
 35:   loop: >-
 36:     {{
 37:       [root_directory] +
 38:       lookup('community.general.filetree',
 39:              directory,
 40:              wantlist = true) |
 41:       selectattr('state', 'eq', 'directory')
 42:     }}
 43:   loop_control:
 44:     label: "{{ item.path }}{{ ' settings=' ~ settings if settings }}"
 45:   notify: "{{ notify_ | default(omit) }}"
 46: 
 47: - name: Copy non-template files
 48:   ansible.builtin.copy:
 49:     src: "{{ item.src }}"
 50:     dest: "{{ target }}/{{ settings.rename | default(item.path) }}"
 51:     owner: "{{ settings.owner | default(omit) }}"
 52:     group: "{{ settings.group | default(omit) }}"
 53:     mode: "{{ settings.mode | default('preserve', true) }}"
 54:   vars:
 55:     settings: >-
 56:       {{
 57:         files[item.path] |
 58:         default(fnmatch_candidates | first) |
 59:         default(None)
 60:       }}
 61:     fnmatch_candidates_yaml: |
 62:       {% for entry in files | ansible.builtin.dict2items %}
 63:       {% if item.path is fnmatch(entry.key) %}
 64:       - # for debugging, the key of the follow object is: {{ entry.key }}
 65:         {{ entry.value }}
 66:       {% endif %}
 67:       {% endfor %}
 68:     fnmatch_candidates: >-
 69:       {{
 70:         fnmatch_candidates_yaml |
 71:         ansible.builtin.from_yaml |
 72:         default([], true) |
 73:         list
 74:       }}
 75:   loop: >-
 76:     {{
 77:       lookup('community.general.filetree',
 78:              directory,
 79:              wantlist = true) |
 80:       selectattr('state', 'eq', 'file') |
 81:       rejectattr('path', 'ansible.builtin.search', '\.j2$') |
 82:       rejectattr('path', 'ansible.builtin.search', '/\.gitignore$')
 83:     }}
 84:   loop_control:
 85:     label: "{{ item.path }}{{ ' settings=' ~ settings if settings }}"
 86:   notify: "{{ notify_ | default(omit) }}"
 87: 
 88: - name: Copy template files
 89:   ansible.builtin.template:
 90:     src: "{{ item.src }}"
 91:     dest: >-
 92:       {{
 93:         target
 94:       }}/{{
 95:         settings.rename |
 96:         default(
 97:           item.path | ansible.builtin.regex_replace('\.j2$', '')
 98:         )
 99:       }}
100:     owner: "{{ settings.owner | default(omit) }}"
101:     group: "{{ settings.group | default(omit) }}"
102:     mode: "{{ settings.mode | default('preserve', true) }}"
103:     lstrip_blocks: true
104:   vars:
105:     settings: >-
106:       {{
107:         files[item.path] |
108:         default(fnmatch_candidates | first) |
109:         default(None)
110:       }}
111:     fnmatch_candidates_yaml: |
112:       {% for entry in files | ansible.builtin.dict2items %}
113:       {% if item.path is fnmatch(entry.key) %}
114:       - # for debugging, the key of the follow object is: {{ entry.key }}
115:         {{ entry.value }}
116:       {% endif %}
117:       {% endfor %}
118:     fnmatch_candidates: >-
119:       {{
120:         fnmatch_candidates_yaml |
121:         ansible.builtin.from_yaml |
122:         default([], true) |
123:         list
124:       }}
125:   loop: >-
126:     {{
127:       lookup('community.general.filetree',
128:              directory,
129:              wantlist = true) |
130:       selectattr('state', 'eq', 'file') |
131:       selectattr('path', 'ansible.builtin.search', '\.j2$') |
132:       rejectattr('path', 'ansible.builtin.search', '/\.gitignore$')
133:     }}
134:   loop_control:
135:     label: "{{ item.path }}{{ ' settings=' ~ settings if settings }}"
136:   notify: "{{ notify_ | default(omit) }}"

 1: - name: Cluster {{ cluster_id }} - Create directories
 2:   file:
 3:     path: "{{ item }}"
 4:     state: directory
 5:     mode: 0755 # For some reason, item.mode converts 0755 into 493 ... weird
 6:   loop:
 7:     - clusters/{{ cluster_id }}
 8: 
 9: - name: Cluster {{ cluster_id }} - Create openshift-install configuration
10:   template:
11:     src: "{{ item.src }}"
12:     dest: "{{ item.dest }}"
13:   vars:
14:     ssh_pub_key: "{{ ssh_pub_key_task.stdout }}"
15:     pull_secret: "{{ lookup('file', './files/pull_secret.txt', errors='ignore') }}"
16:   with_items:
17:     - {
18:         src: templates/install-config.yaml.j2,
19:         dest: "clusters/{{ cluster_id }}/install-config.yaml",
20:       }
21:     - {
22:         src: templates/agent-config.yaml.j2,
23:         dest: "clusters/{{ cluster_id }}/agent-config.yaml",
24:       }
25:   register: okd_installer_config_files
26: 
27: # Let's create the proper OKD installation files (ignition, manifests, ...)
28: - name: Cluster {{ cluster_id }} - Run openshift-installer
29:   when: okd_installer_config_files.changed
30:   shell: |
31:     cd clusters/{{ cluster_id }}
32:     rm -rf install-dir
33:     mkdir install-dir
34:     cp install-config.yaml agent-config.yaml install-dir/
35:     {% if ipxe.enabled %}
36:       {% set cmd = "pxe-files" %}
37:     {% else %}
38:       {% set cmd = "image" %}
39:     {% endif %}
40:     openshift-install agent create {{ cmd }} --dir=install-dir
41:   environment:
42:     PATH: "/usr/local/bin:/usr/bin:/bin"
43:   register: installer_task
44: 
45: # Make these files available on the Web server
46: - name: Cluster {{ cluster_id }} - Copy boot-artifacts to www directory
47:   when: installer_task.changed
48:   become: true
49:   shell: |
50:     rm -rf /var/www/html/{{ cluster_id }}
51:     mkdir /var/www/html/{{ cluster_id }}
52:     {% if ipxe.enabled %}
53:     cp -R clusters/{{ cluster_id }}/install-dir/boot-artifacts/* /var/www/html/{{ cluster_id }}
54:     {% else %}
55:     cp clusters/{{ cluster_id }}/install-dir/agent.x86_64.iso /var/www/html/{{ cluster_id }}/
56:     {% endif %}
57:     chmod -R 755 /var/www/html/{{ cluster_id }}

 1: ---
 2: - name: "Update config for proxy mode"
 3:   when: "bbb_cluster_proxy is defined"
 4:   ansible.builtin.set_fact:
 5:     bbb_config_web_base: |
 6:       {{bbb_config_web_base | combine({
 7:         "defaultHTML5ClientUrl": "https://"+bbb_cluster_proxy+"/"+bbb_cluster_node+"/html5client/",
 8:         "presentationBaseURL": "https://"+bbb_hostname+"/bigbluebutton/presentation",
 9:         "accessControlAllowOrigin": "https://"+bbb_cluster_proxy,
10:         "graphqlWebsocketUrl": "wss://"+bbb_hostname+"/graphql",
11:         "graphqlApiUrl": "https://"+bbb_hostname+"/api/rest"
12:       })}}
13:     bbb_config_html5_base: |
14:       {{bbb_config_html5_base | combine({
15:         'public': {
16:           'app': {
17:             'basename': "/"+bbb_cluster_node+"/html5client",
18:             'bbbWebBase': 'https://'+bbb_hostname+'/bigbluebutton',
19:             'learningDashboardBase': 'https://'+bbb_hostname+'/learning-analytics-dashboard',
20:             'userSettingsStorage': 'local',
21:           },
22:           'media': {
23:             'stunTurnServersFetchAddress': 'https://'+bbb_hostname+'/bigbluebutton/api/stuns',
24:             'sip_ws_host': bbb_hostname,
25:             'livekit': {
26:               'url': 'wss://'+bbb_hostname+'/livekit'
27:             }
28:           },
29:           'kurento': {
30:             'wsUrl': 'wss://'+bbb_hostname+'/bbb-webrtc-sfu'
31:           },
32:           'presentation': {
33:             'uploadEndpoint': 'https://'+bbb_hostname+'/bigbluebutton/presentation/upload'
34:           },
35:           'pads': {
36:             'url': 'https://'+bbb_hostname+'/pad'
37:           }
38:         }
39:       }, recursive=True)}}
40:     bbb_config_etherpad_base: |
41:       {{bbb_config_etherpad_base | combine({
42:         "cluster_proxies": ["https://"+bbb_cluster_proxy]
43:       })}}
44: 
45: - name: Update html5 config for blocknote with proxy mode
46:   when: bbb_cluster_proxy is defined and bbb_shared_notes_editor | lower == 'blocknote'
47:   ansible.builtin.set_fact:
48:     bbb_config_html5_base: |
49:       {{bbb_config_html5_base | combine({
50:         'public': {
51:           'sharedNotes': {
52:             'serverHostname': bbb_hostname
53:           }
54:         }
55:       }, recursive=True)}}

 1: ---
 2: 
 3: # This playbook is used with ansible-pull
 4: #
 5: - hosts: compute
 6:   remote_user: root
 7: 
 8:   # Before the roles
 9:   pre_tasks:
10:     - name: with setup module grab ansible_facts because printing ansible_facts stack traces see ansible github issue 7732
11:       setup:
12:       register: reg_pull_facts
13: 
14:     - name: debug print reg_pull_facts
15:       debug: var=reg_pull_facts
16:       
17:     - name: fetch pull_variables.yml file from pull_install_ip
18:       get_url: url="http://{{ pull_install_ip }}/pull_variables.yml" dest=/root mode=0640
19:       tags: pull
20: 
21:     - name: include_vars the pull_variables.yml
22:       include_vars: /root/pull_variables.yml
23:       tags: pull
24: 
25:     - name: Install ansible
26:       yum: pkg=ansible state=installed
27: 
28:     - name: Configure a cronjob for ansible-pull
29:       cron: name='ansible-pull' user=root 
30:             job='/bin/nice /bin/bash /usr/local/bin/ansible-pull-script.sh >/var/log/ansible.log 2>&1' 
31:             minute="{{ ansible_pull_cron_minute_interval | default('0')}}" 
32:             hour="{{ ansible_pull_cron_hour_interval | default('*/2') }}"
33:             day="{{ ansible_pull_cron_day_interval | default('*') }}"
34:             month="{{ ansible_pull_cron_month_interval | default('*') }}"
35:             weekday="{{ ansible_pull_cron_weekday_interval | default('*') }}"
36:             cron_file=ansible-pull 
37:             state={{ ansible_pull_cron_state | default('present') }}
38:       tags: pull
39: 
40:   roles:
41:   - { role: watermark-release, tags: [ 'always' ]  }
42:   - { role: ansible-role-fgci-repo, tags: [ 'fgci7', 'repos' ] }
43:   - { role: ansible-role-yum, tags: [ 'yum', 'repos', 'login' ] }
44:   - { role: ansible-role-ohpc-repo, tags: [ 'yum', 'repos', 'ohpc' ] }
45:   - { role: network_interface, tags: [ 'network' ] }
46:   - { role: ansible-role-hosts-int, tags: [ 'hosts'] }
47:   - { role: ansible-role-chrony, tags: [ 'ntp', 'chrony' ] }
48:   - { role: ansible-role-autofs, tags: [ 'autofs' ] }
49:   - { role: ansible-role-nis, tags: [ 'nis' ] }
50:   - { role: ansible-role-adauth, tags: [ 'auth' ] }
51:   - { role: ansible-role-pam, tags: [ 'auth', 'pam' ] }
52:   - { role: ansible-role-nsswitch, tags: [ 'nsswitch', 'auth' ] }
53:   - { role: ansible-role-yum-cron-2, tags: [ 'yumcron' ] }
54:   - { role: ansible-role-cuda, tags: [ 'cuda', 'nvidia' ] }
55:   - { role: ansible-role-rsyslog, tags: [ 'rsyslog' ] }
56:   - { role: ansible-role-aliases, tags: [ 'aliases', 'email' ] }
57:   - { role: ansible-role-postfix, tags: [ 'postfix', 'mail' ] }
58:   - { role: ansible-role-idmapd, tags: [ 'idmapd' ] }
59:   - { role: ansible-role-nfs_mount, tags: [ 'nfsmount' ] }
60:   - { role: ansible-role-sshd-host-keys, tags: [ 'sshd', 'ssh', 'host-keys' ] }
61:   - { role: ansible-role-nhc, tags: [ 'nhc', 'slurm' ] }
